-- ----- 20261009000300_security.sql -----
-- Contest Scoreboard: row-level security, grants, storage, realtime.
-- Principle: anon gets nothing. authenticated may SELECT (filtered by RLS) and call a short list
-- of RPCs. All writes go through security-definer RPCs or Edge Functions.

-- ---------------------------------------------------------------------------------------------
-- Lock everything down first, then grant back what is needed
-- ---------------------------------------------------------------------------------------------
revoke all on all tables in schema public from public, anon, authenticated;
revoke all on all sequences in schema public from public, anon, authenticated;
-- (Functions that belong to an extension, e.g. citext's operators, must stay executable by everyone.)
do $$
declare r record;
begin
  for r in
    select p.oid::regprocedure as sig
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and not exists (select 1 from pg_depend d where d.objid = p.oid and d.deptype = 'e')
  loop
    execute format('revoke all on function %s from public, anon, authenticated', r.sig);
  end loop;
end $$;

-- Objects created by later migrations start closed too.
alter default privileges in schema public revoke all on tables from public, anon, authenticated;
alter default privileges in schema public revoke all on sequences from public, anon, authenticated;
alter default privileges in schema public revoke all on functions from public, anon, authenticated;

-- service_role (Apps Script, Edge Functions) keeps full access, except to rewrite history.
grant all on all tables in schema public to service_role;
grant all on all sequences in schema public to service_role;
grant execute on all functions in schema public to service_role;
revoke all on audit_log from service_role;
grant select on audit_log to service_role;

-- ---------------------------------------------------------------------------------------------
-- Row-level security
-- ---------------------------------------------------------------------------------------------
alter table contests       enable row level security;
alter table members        enable row level security;
alter table admins         enable row level security;
alter table categories     enable row level security;
alter table submissions    enable row level security;
alter table audit_log      enable row level security;
alter table key_requests   enable row level security;  -- no policies: nobody via the API
alter table login_attempts enable row level security;  -- no policies: nobody via the API

grant select on contests, members, admins, categories, submissions, audit_log to authenticated;
grant execute on function is_admin(), is_owner(), is_member(), current_contest_id() to authenticated;

create policy contests_select on contests for select to authenticated
  using (is_member() or is_admin());

create policy members_select on members for select to authenticated
  using (id = auth.uid() or is_admin());

create policy admins_select on admins for select to authenticated
  using (is_admin());

create policy categories_select on categories for select to authenticated
  using ((active and contest_id = current_contest_id() and is_member()) or is_admin());

create policy submissions_select on submissions for select to authenticated
  using ((member_id = auth.uid() and is_member()) or is_admin());

create policy audit_log_select on audit_log for select to authenticated
  using (is_admin());

-- ---------------------------------------------------------------------------------------------
-- RPC execute grants (everything else stays closed; service_role has all)
-- ---------------------------------------------------------------------------------------------
grant execute on function
  get_leaderboard(), get_admin_leaderboard(), get_contest_banner(),
  create_submission_draft(uuid, text, text, text, uuid),
  withdraw_submission(uuid), my_resubmission_allowance(uuid), my_submissions(),
  claim_submission(uuid), approve_submission(uuid), reject_submission(uuid, text, text),
  reverse_submission(uuid, text), correct_rejection(uuid, text), grant_override(uuid, text),
  set_member_active(uuid, boolean),
  upsert_category(uuid, text, int, text, text, int), set_category_active(uuid, boolean),
  update_contest_setup(text, timestamptz, timestamptz, int),
  set_points_unlocked(boolean, text), extend_deadline(timestamptz, text),
  publish_final(text), reopen_contest(text), owner_mark_exported(), archive_contest(text),
  owner_add_admin(uuid, citext, admin_role), owner_set_admin_active(uuid, boolean)
to authenticated;

-- Auth hook (only takes effect once enabled in Auth settings, Teams/Enterprise plans).
grant usage on schema public to supabase_auth_admin;
grant execute on function hook_password_verification_attempt(jsonb) to supabase_auth_admin;

-- ---------------------------------------------------------------------------------------------
-- Realtime: members watch their own submissions (RLS limits what each subscriber receives)
-- ---------------------------------------------------------------------------------------------
do $$ begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    alter publication supabase_realtime add table submissions;
  end if;
end $$;

-- ---------------------------------------------------------------------------------------------
-- Storage: private "proofs" bucket. Path: {contest_id}/{member_id}/{submission_id}.{ext}
-- Uploads happen only through signed upload URLs issued by create-submission-draft, so there is
-- deliberately no INSERT/UPDATE/DELETE policy for end users.
-- ---------------------------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('proofs', 'proofs', false, 2097152, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update
  set public = false, file_size_limit = 2097152,
      allowed_mime_types = array['image/jpeg', 'image/png', 'image/webp'];

create policy proofs_select on storage.objects for select to authenticated
  using (
    bucket_id = 'proofs'
    and ((storage.foldername(name))[2] = auth.uid()::text and is_member() or is_admin())
  );

